// Original synthetic survey and kinematic fixtures, unrelated to proprietary coordinates.
using System;using System.IO;using System.Linq;using System.Runtime.Serialization.Json;
using RichAudio.AirportResearch;using RichAudio.BatiResearch;using RichAudio.MarkerResearch;using RichAudio.GeometryResearch;
public static class FiveStopTests
{
 static int tests;static void Yes(bool b,string why){tests++;if(!b)throw new Exception(why);}static void Reject(Action a,string why){bool threw=false;try{a();}catch{threw=true;}Yes(threw,why);}
 static byte[] Json<T>(T o){using(var m=new MemoryStream()){new DataContractJsonSerializer(typeof(T)).WriteObject(m,o);return m.ToArray();}}
 static MarkerSet Markers(){var p=new MarkerPlan("original-synthetic-fixture","markers-five");p.Set(MarkerKind.Start,new MarkerPose{Position=new MarkerPoint(0,0,1),AtMs=1});p.Set(MarkerKind.Finish,new MarkerPose{Position=new MarkerPoint(100,0,1),AtMs=2});var r=p.Set(MarkerKind.Listener,new MarkerPose{Position=new MarkerPoint(50,20,4),AtMs=3,OnFoot=true});var b=Json(r);return MarkerSet.Parse(b,Check.Hash(b),3,"markers-five","original-synthetic-fixture");}
 static GeometryObservation O(Ray r,Pose p){bool body=r.Role!="ground-probe";return new GeometryObservation{SessionId="five-survey",GameVersion="1.0.1158.16",FrameworkVersion="1.132.1428.17748",Origin=r.Origin,End=r.End,MaximumDistance=Point3.Sub(r.End,r.Origin).Length,ObservedAtMs=p.AtMs+1,TraceDurationMs=.01,ConversionDurationMs=.01,TraceCalls=1,IgnoredPlayerHandle=p.Player,PlayerSpeed=0,SetupStatus="on_foot_stationary_by_SDK_getters",QueryProvenance=body?"airport-body-line-v1":"airport-ground-probe-v1",Completion=body?"miss":"hit",HitPosition=body?(Point3?)null:new Point3(r.Origin.X,r.Origin.Y,0),HitNormal=body?(Point3?)null:new Point3(0,0,1),PositionStatus=body?"not_returned_miss":"observed",NormalStatus=body?"not_returned_miss":"observed",EntityStatus=body?"not_returned_miss":"none_returned_static_unproven"};}
 static string[] SurveyFiles(string root,MarkerSet m){Directory.CreateDirectory(root);var s=new Survey(m,"five-survey");for(int j=0;j<5;j++){var p=new Pose{AtMs=100+j*1000,Position=new MarkerPoint(j*25,0,1),Forward=new MarkerPoint(1,0,0),OnFoot=true,Player=42,Generation=1};var g=s.Begin((StopKind)j,p);while(g.ActualCalls<g.Plan.Count){var ray=s.ClaimRay(p);s.Accept(O(ray,p));g=s.Snapshot().Stops.Last();}s.Complete(new Navigation{Calls=2,NodesLoaded=true,TravelEstimate=100-j*25},new Interference{Enumerations=3,AtMs=p.AtMs+2},p.AtMs+3);SurveyPersistence.Save(Path.Combine(root,"stop-"+(j+1)+".json"),s.Snapshot());}s.Stop("subsequent RUNOUT setup failed; five stops retained");SurveyPersistence.Save(Path.Combine(root,"closed.json"),s.Snapshot());return Enumerable.Range(1,5).Select(i=>Check.Hash(File.ReadAllBytes(Path.Combine(root,"stop-"+i+".json")))).Concat(new[]{Check.Hash(File.ReadAllBytes(Path.Combine(root,"closed.json")))}).ToArray();}
 static RouteEvidence Route(MarkerSet m,AirportRouteCandidate c){return new RouteEvidence{Domain=m.Domain,Session="five-run",MarkerFingerprint=m.Fingerprint,Revision=c.Revision,Points=(MarkerPoint[])c.Points.Clone(),Candidate=c,BoundedResearch=true,SpawnPlacementReviewed=true,CurrentScopeReviewed=true,BrakingReviewed=true,CleanupReviewed=true,CoverageComplete=false,TrafficIsolationVerified=false};}
 static Controller Ready(MarkerSet m,AirportRouteCandidate c,FakeWorld w,Policy p=null){var controller=new Controller(m,p??new Policy(),w,"five-run");controller.Prepare(Route(m,c));controller.Arm(true);Yes(controller.Start(0),"one synthetic creation");return controller;}
 static Reading R(Controller c,double t,double x,double v){var s=c.Snapshot();return new Reading{At=t,Domain="original-synthetic-fixture",Bike=s.Bike,Rider=s.Rider,Position=new MarkerPoint(x,0,1),Velocity=new MarkerPoint(v,0,0),PlayerPosition=new MarkerPoint(50,20,4),PlayerVelocity=new MarkerPoint(),Rotation=new MarkerPoint(),Speed=v,Mounted=true,EngineOn=true,Simulation="OBSERVED_CONTIGUOUS",Interference="NONE_OBSERVED_IN_MONITORED_SCOPE"};}
 static void ToFinish(Controller c){for(int i=0;i<=120&&c.State!=Stage.Stopping&&c.State!=Stage.Cleaned;i++){double t=i*.1,x=t<=2?2.5*t*t:10+10*(t-2),v=t<=2?5*t:10;c.Observe(R(c,t,x,v));}Yes(c.State==Stage.Stopping,"finish reached into stopping, not complete");}
 public static int Main(string[] args)
 {
  string root=args[0];Directory.CreateDirectory(root);var m=Markers();string survey=Path.Combine(root,"survey");var pins=SurveyFiles(survey,m);var candidate=FiveStopRoute.Load(survey,m,pins);Yes(candidate.Points.Length==5&&!candidate.RunoutRequired&&!candidate.ContinuousClearanceVerified&&!candidate.LiveStartApproved,"no sixth observation or false authority");Yes(candidate.Points.Select(p=>p.X).SequenceEqual(new double[]{0,25,50,75,100})&&candidate.Points[0].Z==1&&candidate.StartSupport.Z==0,"exact measured anchors and separate ground support");Yes(!File.Exists(Path.Combine(survey,"stop-6.json")),"no RUNOUT source required");
  var copy=candidate.Copy();copy.Points[1]=new MarkerPoint(999,0,0);Yes(candidate.Points[1].X==25,"copied candidate points");var b=File.ReadAllBytes(Path.Combine(survey,"stop-5.json"));var r=FiveStopRoute.Parse(b);
  foreach(var mutate in new Action<SurveyRecord>[] {x=>x.Session=null,x=>x.ActualCalls=31,x=>x.MarkerRevision=4,x=>x.RouteClear=true,x=>x.Stops[0].Player.OnFoot=false,x=>x.Stops[1].Kind="Runout",x=>x.Stops[2].Observations[0].IgnoredPlayerHandle=99,x=>x.Stops[3].Plan[0].Origin=new Point3(),x=>x.Stops[4].Completion="STOPPED",x=>x.Stops[0].Observations[0].HitNormal=new Point3(),x=>x.OriginalListener=new MarkerPoint(),x=>x.Stops[0].Surface="VERIFIED"}){var bad=FiveStopRoute.Parse(b);mutate(bad);Reject(()=>FiveStopRoute.ValidateSnapshot(bad,5,m),"invalid source snapshot rejected");}
  var wrong=(string[])pins.Clone();wrong[0]=new string('0',64);Reject(()=>FiveStopRoute.Load(survey,m,wrong),"pins enforced");Reject(()=>FiveStopRoute.Load(survey,m,pins.Take(5).ToArray()),"closed fingerprint required, not RUNOUT");Reject(()=>FiveStopRoute.Parse(new byte[2097153]),"allocation bound");Reject(()=>FiveStopRoute.Parse(new byte[]{1}),"invalid JSON");
  var w=new FakeWorld();var ctl=new Controller(m,new Policy(),w,"five-run");var route=Route(m,candidate);ctl.Prepare(route);Yes(ctl.State==Stage.Ready&&w.Spawns==0,"historical candidate can prepare without full coverage/RUNOUT, not spawn");Reject(()=>ctl.Arm(false),"separate approval required");
  foreach(string missing in new[]{"spawn","scope","brake","cleanup"}){route=Route(m,candidate);if(missing=="spawn")route.SpawnPlacementReviewed=false;if(missing=="scope")route.CurrentScopeReviewed=false;if(missing=="brake")route.BrakingReviewed=false;if(missing=="cleanup")route.CleanupReviewed=false;var q=new Controller(m,new Policy(),new FakeWorld(),"five-run");Reject(()=>q.Prepare(route),"current preflight not bypassed: "+missing);}
  w=new FakeWorld();ctl=Ready(m,candidate,w);ToFinish(ctl);var at=ctl.Snapshot().Stopping.FinishObservedAt.Value;var x0=ctl.Snapshot().Stopping.FinishObservationPosition.Value.X;Yes(w.Brakes==1&&w.Deleted.Count==0&&!ctl.Snapshot().Stopping.StationaryConfirmed,"one natural brake request; no moving cleanup/completion");
  for(int i=1;i<=36&&ctl.State!=Stage.Cleaned;i++){double t=i*.1,u=Math.Min(t,2),x=x0+10*u-2.5*u*u,v=Math.Max(0,10-5*t);ctl.Observe(R(ctl,at+t,x,v));}var done=ctl.Snapshot();Yes(done.Stopping.StationaryConfirmed&&ctl.State==Stage.Cleaned&&done.Cleanup=="VERIFIED_ABSENT","stationary hold then cleanup");Yes(Math.Abs(done.Stopping.SampledDistanceAfterFinishDetection-10)<1e-8&&Math.Abs(done.Stopping.IntegratedDistanceAfterFinishDetection-10)<1e-8,"independent constant-deceleration distance integral 10");Yes(done.Stopping.StoppingSeconds>=3&&done.Stopping.StationaryObservedSeconds>=1&&done.Stopping.StopPosition.Value.X>x0,"overshoot measured, no teleport or velocity forcing");Yes(w.Drives==4&&w.Brakes==1&&done.Lifecycle.Count(e=>e.StartsWith("observed checkpoint"))==4,"all four next checkpoints observed in order");PrivateFiles.WriteNew(Path.Combine(root,"stopping-run.json"),done);
  foreach(string mode in new[]{"brake","timeout","gap","moving","interference","identity","abort","distance"}){
   w=new FakeWorld{BrakeFailure=mode=="brake"};ctl=Ready(m,candidate,w);if(mode=="brake"){for(int i=0;i<=120&&ctl.State!=Stage.Cleaned;i++){double t=i*.1,x=t<2?2.5*t*t:10+10*(t-2),v=t<2?5*t:10;ctl.Observe(R(ctl,t,x,v));}Yes(ctl.Snapshot().Outcome=="FAILED"&&!ctl.Snapshot().Stopping.StationaryConfirmed,"brake request failure never success");continue;}
   ToFinish(ctl);var s=ctl.Snapshot().Stopping;at=s.FinishObservedAt.Value;x0=s.FinishObservationPosition.Value.X;
   if(mode=="timeout")ctl.Tick(at+20.1);else if(mode=="gap")ctl.Observe(R(ctl,at+.3,x0+3,10));else if(mode=="abort")ctl.Abort();else if(mode=="interference"){var bad=R(ctl,at+.1,x0+1,10);bad.Interference="DETECTED";ctl.Observe(bad);}else if(mode=="identity"){var bad=R(ctl,at+.1,x0+1,10);bad.Bike.Generation++;ctl.Observe(bad);}else{double speed=mode=="moving"?1:10;for(int i=1;i<=210&&ctl.State!=Stage.Cleaned;i++)ctl.Observe(R(ctl,at+i*.1,x0+i*.1*speed,speed));}
   Yes(!ctl.Snapshot().Stopping.StationaryConfirmed&&!ctl.Snapshot().Outcome.Contains("STATIONARY_CONFIRMED"),"stopping failure cannot claim completion: "+mode);
   if(mode=="distance")Yes(ctl.Snapshot().Reason.Contains("distance"),"distance cap independently triggers before deadline");if(mode=="moving")Yes(ctl.Snapshot().Reason.Contains("timeout"),"persistent slow movement reaches deadline without false stop");
  }
  w=new FakeWorld();ctl=Ready(m,candidate,w);ToFinish(ctl);at=ctl.Snapshot().Stopping.FinishObservedAt.Value;x0=ctl.Snapshot().Stopping.FinishObservationPosition.Value.X;for(int i=1;i<=5;i++)ctl.Observe(R(ctl,at+i*.1,x0,0));Yes(!ctl.Snapshot().Stopping.StationaryConfirmed,"one zero reading insufficient");ctl.Observe(R(ctl,at+.6,x0+.05,.5));Yes(!ctl.Snapshot().Stopping.StationarySince.HasValue,"resumed movement resets hold");ctl.Abort();
  Reject(()=>new Policy{MaximumStoppingSeconds=21}.Validate(),"stop deadline bound");Reject(()=>new Policy{StationarySpeed=1}.Validate(),"stationary threshold bound");Reject(()=>new Policy{DrivingStyle=32}.Validate(),"unsupported driving policy");
  var now=DateTime.UtcNow;string nonce=new string('a',32),binary=new string('b',64),fingerprint=new string('c',64);
  var approval=new ExperimentApproval{Version=1,Approved=true,StoryModeOnly=true,MaximumRuns=1,MaximumEntities=2,ScopeNonce=nonce,BinaryFingerprint=binary,CandidateFingerprint=fingerprint,ExpiresUtc=now.AddMinutes(30).ToString("o")};approval.Validate(nonce,binary,fingerprint,now);Yes(true,"bound separate approval accepted");
  foreach(var mutate in new Action<ExperimentApproval>[] {a=>a.Approved=false,a=>a.StoryModeOnly=false,a=>a.MaximumRuns=2,a=>a.MaximumEntities=3,a=>a.ScopeNonce="other",a=>a.BinaryFingerprint=null,a=>a.CandidateFingerprint=new string('d',64),a=>a.ExpiresUtc=now.AddSeconds(-1).ToString("o"),a=>a.ExpiresUtc=now.AddHours(3).ToString("o")}){ExperimentApproval q;using(var stream=new MemoryStream(Json(approval)))q=(ExperimentApproval)new DataContractJsonSerializer(typeof(ExperimentApproval)).ReadObject(stream);mutate(q);Reject(()=>q.Validate(nonce,binary,fingerprint,now),"bad/stale/unbound approval rejected");}
  Yes(PresenceProof.Assess(true,true,false,false,false)==Presence.Absent,"saved native GUID and invalid wrapper jointly establish observed absence");
  Yes(PresenceProof.Assess(true,true,true,true,true)==Presence.Present,"matching native and wrapper present");
  Yes(PresenceProof.Assess(true,true,true,true,false)==Presence.Reused,"reused handle never owned");
  foreach(var v in new[]{PresenceProof.Assess(true,true,null,false,false),PresenceProof.Assess(true,false,false,false,false),PresenceProof.Assess(false,true,false,false,false),PresenceProof.Assess(true,true,true,false,false),PresenceProof.Assess(true,true,false,true,true)})Yes(v==Presence.Unknown,"wrapper invalidation or contradictory/unavailable native proof is insufficient");
  string streamFile=Path.Combine(root,"copied.jsonl");var input=R(ctl,1,2,3);using(var writer=new ExperimentWriter(streamFile)){Yes(writer.Add(input),"copied observation queued");input.Speed=999;writer.Dispose();Yes(writer.Closed&&!writer.Failed,"writer joined and flushed");}Reading stored;using(var stream=new MemoryStream(System.Text.Encoding.UTF8.GetBytes(File.ReadLines(streamFile).Single())))stored=(Reading)new DataContractJsonSerializer(typeof(Reading)).ReadObject(stream);Yes(stored.Speed==3,"writer does not share mutable game observation");Reject(()=>new ExperimentWriter(streamFile),"no stream overwrite");Reject(()=>new ExperimentWriter(Path.Combine(Path.GetTempPath(),"not-private.jsonl")),"private storage required");
  Console.WriteLine("PASS: "+tests+" five-stop validation and measured-stopping assertions; original synthetic data only.");return 0;
 }
